/**
 * 生成 README.html 在 file:// 下可读的 Markdown 内容包。
 * 用法：node script/build-md-bundle.js
 */
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const outFile = path.join(__dirname, "md-bundle.js");

function walk(dir, acc = []) {
  if (!fs.existsSync(dir)) return acc;
  for (const name of fs.readdirSync(dir)) {
    if (name === "node_modules" || name === ".git") continue;
    if (dir === root && (name === "language" || name === "script")) continue;
    const p = path.join(dir, name);
    let st;
    try {
      st = fs.statSync(p);
    } catch {
      continue;
    }
    if (st.isDirectory()) walk(p, acc);
    else if (name.toLowerCase().endsWith(".md")) acc.push(p);
  }
  return acc;
}

const map = {};
for (const file of walk(root)) {
  const rel = path.relative(root, file).split(path.sep).join("/");
  map[rel] = fs.readFileSync(file, "utf8");
}

const body =
  "/* Auto-generated by script/build-md-bundle.js — do not edit by hand */\n" +
  "window.__MD_BUNDLE__ = " +
  JSON.stringify(map) +
  ";\n";

fs.writeFileSync(outFile, body, "utf8");
console.log(
  "Wrote",
  path.relative(root, outFile),
  "(" + Object.keys(map).length + " files, " + body.length + " bytes)"
);
